#include <windows.h>
#include <d3d8.h>
// Complete 154-byte original R235 scene-resource destructor; real
// C++ derived virtual scene vtable and native /GX EH are generated by VC7.1.
// Only the observed 8-byte base ABI, texture pointer at +8 and owned
// D3D8 canvas at +0xC are modeled; no full private scene type layout.
// Borrowed 8-byte native scene base, texture pointer and D3D canvas.
class OptionsBaseF432 {void* nativeConfig;public:OptionsBaseF432();virtual ~OptionsBaseF432();};
class OptionTextureF432 {public: ~OptionTextureF432();};
class OptionsSceneF432 : public OptionsBaseF432 {
   OptionTextureF432* texture;
   IDirect3DTexture8* canvas;
public:OptionsSceneF432();virtual ~OptionsSceneF432();
};
OptionsSceneF432::~OptionsSceneF432() {
 if(texture) delete texture;
 if(canvas) canvas->Release();
}
